import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildReviewedRecordDepthBaseline } from './growth/build-reviewed-record-depth-baseline-pr353.mjs';

// The bootstrap workflow commits the deterministic outputs generated by this builder.
const root = process.cwd();
const paths = {
  config: 'config/record-depth-baseline-refresh-pr363.json',
  reviewGate: 'docs/migration/post-pr360-review-gate-pr361.json',
  historicalSummary: 'docs/migration/record-depth-baseline-pr353-summary.json',
  historicalQueue: 'docs/migration/tier-a-candidate-queue-pr353.json',
  growthHandoff: 'docs/migration/record-growth-batch-1-pr358-reviewed-handoff.json',
  canonicalCheckpoint: 'docs/migration/current-canonical-checkpoint.json'
};
const outputPaths = {
  summary: 'docs/migration/record-depth-baseline-pr363-summary.json',
  delta: 'docs/migration/record-depth-baseline-pr363-delta.json',
  queue: 'docs/migration/tier-a-candidate-queue-pr363.json'
};
const readText = (file) => fs.readFileSync(path.join(root, file), 'utf8');
const readJson = (file) => JSON.parse(readText(file));
const sorted = (values) => [...new Set(values)].sort();
const stateOrder = ['strong', 'usable', 'partial', 'sparse', 'absent', 'not_applicable'];
const stateCounts = (rows) => Object.fromEntries(stateOrder.map((state) => [state, rows.filter((row) => row.state === state).length]));
const diffCounts = (before, after) => Object.fromEntries(stateOrder.map((state) => [state, (after[state] ?? 0) - (before[state] ?? 0)]));
const serialize = (value) => `${JSON.stringify(value, null, 2)}\n`;

function generationDigest(current) {
  const digest = crypto.createHash('sha256');
  for (const file of Object.values(paths).sort()) {
    digest.update(file);
    digest.update('\0');
    digest.update(readText(file));
    digest.update('\0');
  }
  digest.update(current.input_digest_sha256);
  return digest.digest('hex');
}

export function buildRecordDepthRefreshOutputs() {
  const config = readJson(paths.config);
  const reviewGate = readJson(paths.reviewGate);
  const historicalSummary = readJson(paths.historicalSummary);
  const historicalQueue = readJson(paths.historicalQueue);
  const growthHandoff = readJson(paths.growthHandoff);
  const checkpoint = readJson(paths.canonicalCheckpoint);
  const current = buildReviewedRecordDepthBaseline();
  const currentQueue = current.tier_a_candidate_queue;
  const digest = generationDigest(current);

  const historicalDimensionById = new Map(historicalSummary.summary.dimension_states.map((row) => [row.dimension_id, row.state_counts]));
  const currentDimensionById = new Map(current.summary.dimension_states.map((row) => [row.dimension_id, row.state_counts]));
  const dimensionDeltas = current.dimension_order.map((dimensionId) => {
    const before = historicalDimensionById.get(dimensionId) ?? {};
    const after = currentDimensionById.get(dimensionId) ?? {};
    return {
      dimension_id: dimensionId,
      before,
      after,
      delta: diffCounts(before, after),
      unresolved_before: (before.partial ?? 0) + (before.sparse ?? 0) + (before.absent ?? 0),
      unresolved_after: (after.partial ?? 0) + (after.sparse ?? 0) + (after.absent ?? 0)
    };
  });

  const historicalCandidateIds = sorted(historicalQueue.candidates.map((row) => row.asset_id));
  const currentCandidateIds = sorted(currentQueue.map((row) => row.asset_id));
  const historicalSet = new Set(historicalCandidateIds);
  const currentSet = new Set(currentCandidateIds);
  const promotedAssetIds = sorted(growthHandoff.promoted_asset_ids ?? []);
  const promotedSet = new Set(promotedAssetIds);
  const promotedAssets = current.assets
    .filter((asset) => promotedSet.has(asset.asset_id))
    .sort((a, b) => a.asset_slug.localeCompare(b.asset_slug))
    .map((asset) => ({
      asset_id: asset.asset_id,
      asset_slug: asset.asset_slug,
      asset_name: asset.asset_name,
      symbol: asset.symbol,
      state_counts: stateCounts(asset.dimension_states),
      priority_gaps: asset.priority_gaps,
      dimension_states: asset.dimension_states
    }));

  const summary = {
    schema_version: '1.0',
    baseline_id: 'sog_record_depth_baseline_pr363_v1',
    status: 'reviewed_internal_planning_checkpoint',
    public_output: false,
    asset_rank: false,
    single_composite_score: false,
    review_pr: 363,
    reviewed_at: config.reviewed_at,
    source_review_gate_id: reviewGate.report_id,
    source_canonical_checkpoint_id: checkpoint.checkpoint_id,
    source_stats_checkpoint_id: reviewGate.current_stats_checkpoint_id,
    historical_baseline_id: historicalSummary.baseline_id,
    asset_count: current.asset_count,
    dimension_count: current.dimension_count,
    cell_count: current.cell_count,
    planning_states: current.planning_states,
    dimension_order: current.dimension_order,
    input_digest_sha256: current.input_digest_sha256,
    generation_digest_sha256: digest,
    source_contracts: current.source_contracts,
    summary: current.summary,
    queue_order: current.queue_order,
    next_work_item: config.next_work_item
  };

  const delta = {
    schema_version: '1.0',
    delta_id: 'sog_record_depth_baseline_delta_pr353_to_pr363_v1',
    status: 'reviewed_internal_planning_delta',
    public_output: false,
    asset_rank: false,
    review_pr: 363,
    reviewed_at: config.reviewed_at,
    historical_baseline_id: historicalSummary.baseline_id,
    current_baseline_id: summary.baseline_id,
    historical_input_digest_sha256: historicalSummary.input_digest_sha256,
    current_input_digest_sha256: current.input_digest_sha256,
    generation_digest_sha256: digest,
    asset_count: {
      before: historicalSummary.asset_count,
      after: current.asset_count,
      delta: current.asset_count - historicalSummary.asset_count
    },
    cell_count: {
      before: historicalSummary.cell_count,
      after: current.cell_count,
      delta: current.cell_count - historicalSummary.cell_count
    },
    state_counts: {
      before: historicalSummary.summary.state_counts,
      after: current.summary.state_counts,
      delta: diffCounts(historicalSummary.summary.state_counts, current.summary.state_counts)
    },
    dimension_deltas: dimensionDeltas,
    candidate_queue: {
      before_count: historicalQueue.candidate_count,
      after_count: currentQueue.length,
      delta: currentQueue.length - historicalQueue.candidate_count,
      continuing_asset_ids: currentCandidateIds.filter((id) => historicalSet.has(id)),
      exited_asset_ids: historicalCandidateIds.filter((id) => !currentSet.has(id)),
      entered_asset_ids: currentCandidateIds.filter((id) => !historicalSet.has(id))
    },
    canonical_assets_added_since_pr353: {
      source_handoff_id: growthHandoff.handoff_id,
      asset_ids: promotedAssetIds,
      assets: promotedAssets,
      interpretation_boundary: 'These rows describe the current contribution of the two added assets. Other state deltas may reflect later dossier, Market Access, or Evidence work and are not attributed to the additions.'
    },
    historical_checkpoint_rewritten: false
  };

  const queue = {
    schema_version: '1.0',
    baseline_id: summary.baseline_id,
    status: 'internal_reviewed_planning_queue',
    public_output: false,
    asset_rank: false,
    single_composite_score: false,
    review_pr: 363,
    reviewed_at: config.reviewed_at,
    queue_order: current.queue_order,
    candidate_count: currentQueue.length,
    input_digest_sha256: current.input_digest_sha256,
    generation_digest_sha256: digest,
    source_review_gate_id: reviewGate.report_id,
    source_contracts: current.source_contracts,
    selection_boundary: {
      canonical_promotion_authorized: false,
      manual_review_required: true,
      maximum_assets_in_pr364: config.queue_policy.maximum_assets_in_pr364
    },
    candidates: currentQueue
  };

  return { summary, delta, queue };
}

export function writeRecordDepthRefreshOutputs(outputs = buildRecordDepthRefreshOutputs()) {
  for (const [key, file] of Object.entries(outputPaths)) {
    fs.mkdirSync(path.dirname(path.join(root, file)), { recursive: true });
    fs.writeFileSync(path.join(root, file), serialize(outputs[key]));
  }
  return outputPaths;
}

const isCli = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isCli) {
  const outputs = buildRecordDepthRefreshOutputs();
  writeRecordDepthRefreshOutputs(outputs);
  console.log(JSON.stringify({
    ok: true,
    baseline_id: outputs.summary.baseline_id,
    assets: outputs.summary.asset_count,
    dimensions: outputs.summary.dimension_count,
    cells: outputs.summary.cell_count,
    candidates: outputs.queue.candidate_count,
    generation_digest_sha256: outputs.summary.generation_digest_sha256,
    outputs: outputPaths
  }, null, 2));
}
